const managerChain = `-- name: ManagerChain :many
WITH RECURSIVE up AS (
    SELECT e.manager_id FROM employees e WHERE e.user_id = $1
    UNION
    SELECT e.manager_id FROM employees e JOIN up ON e.user_id = up.manager_id
)
SELECT manager_id::uuid FROM up WHERE manager_id IS NOT NULL
`

// Everyone above the person in the reporting line (UNION stops on a cycle).
func (q *Queries) ManagerChain(ctx context.Context, userID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, managerChain, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var manager_id uuid.UUID
		if err := rows.Scan(&manager_id); err != nil {
			return nil, err
		}
		items = append(items, manager_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportIDs = `-- name: ReportIDs :many
WITH RECURSIVE down AS (
    SELECT e.user_id FROM employees e WHERE e.manager_id = $1::uuid
    UNION
    SELECT e.user_id FROM employees e JOIN down d ON e.manager_id = d.user_id
)
SELECT user_id FROM down
`

